"""Amalgamate the private C++ wrapper sources into one standalone public header."""

import argparse
from pathlib import Path
import re


def generate(root):
    public = root / "include" / "communicationdriver"
    sources = root / "src" / "api" / "cpp"
    parts = [
        "types",
        "check",
        "options",
        "results",
        "operation",
        "connection",
        "driver",
        "response_checker",
        "batch",
    ]
    result = (
        "#pragma once\n"
        "// Generated by scripts/generate_cpp_header.py; edit src/api/cpp/ instead.\n"
        "// The C ABI is embedded so this header can be distributed on its own.\n\n"
        + (public / "communicationdriver.h").read_text()
    )
    for name in parts:
        source = (sources / (name + ".hpp")).read_text()
        source = re.sub(
            r'^#pragma once\n|^#include ["<](?:communicationdriver/communicationdriver.h|[^">]+\.hpp)[">]\n',
            "",
            source,
            flags=re.MULTILINE,
        )
        result += "\n// C++ wrapper: " + name + "\n" + source
    return result


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--check", action="store_true")
    args = parser.parse_args()
    root = Path(__file__).resolve().parents[1]
    target = root / "include/communicationdriver/communicationdriver.hpp"
    content = generate(root)
    if args.check:
        if target.read_text() != content:
            raise SystemExit(
                "Public C++ header is stale; run python3 scripts/generate_cpp_header.py"
            )
        print("PASS standalone C++ header is up to date")
    else:
        target.write_text(content)


if __name__ == "__main__":
    main()
